1	/**
2	 * app.ts
3	 *
4	 * Hono application: middleware, setup gate, upload endpoints, and the
5	 * main `/api/*` catch-all that dispatches to transport-agnostic handlers.
6	 *
7	 * Exported as `app` so the thin `api.ts` entry point can call `app.fetch()`.
8	 */
9	
10	import { Hono } from "hono";
11	import { createSetupApp } from "./setup.js";
12	import { buildRequestResources } from "./route-registry.js";
13	import { resolveActorFromRequest } from "../auth/resolve-actor.js";
14	import { registerUploadHandlers } from "./upload-handlers.js";
15	import { registerCfExtraRoutes } from "./cf-extra-routes.js";
16	import { HttpError } from "../../../../server/src/errors.js";
17	import type { Env } from "./env.js";
18	import { resolveDeploymentMode } from "./env.js";
19	
20	export const app = new Hono<{ Bindings: Env }>();
21	
22	// ---------------------------------------------------------------------------
23	// Health check — always reachable, no auth, no setup gate
24	// ---------------------------------------------------------------------------
25	
26	app.get("/api/health", (c) =>
27	  c.json({
28	    status: "ok",
29	    platform: c.env.DEPLOYMENT_PLATFORM ?? "cloudflare",
30	    mode: c.env.DEPLOYMENT_MODE ?? "authenticated",
31	    ts: new Date().toISOString(),
32	  }),
33	);
34	
35	// ---------------------------------------------------------------------------
36	// First-run setup gate
37	//
38	// Redirects all non-health, non-setup traffic to /setup until the operator
39	// completes first-run configuration. Bypassed in `local_trusted` mode.
40	// ---------------------------------------------------------------------------
41	
42	app.use("*", async (c, next) => {
43	  if (c.req.path === "/api/health" || c.req.path.startsWith("/setup")) {
44	    return next();
45	  }
46	  if (c.env.DEPLOYMENT_MODE === "local_trusted") {
47	    return next();
48	  }
49	  const setupCompleted = await c.env.PAPERCLIP_KV.get("SETUP_COMPLETED");
50	  if (setupCompleted !== "true") {
51	    return c.redirect("/setup");
52	  }
53	  return next();
54	});
55	
56	// ---------------------------------------------------------------------------
57	// Setup sub-app (strips /setup prefix and forwards to the setup Hono app)
58	// ---------------------------------------------------------------------------
59	
60	app.all("/setup/*", async (c) => {
61	  const setupSub = createSetupApp(c.env);
62	  const url = new URL(c.req.url);
63	  url.pathname = url.pathname.replace(/^\/setup/, "") || "/";
64	  return setupSub.fetch(new Request(url.toString(), c.req.raw));
65	});
66	
67	app.all("/setup", async (c) => {
68	  const setupSub = createSetupApp(c.env);
69	  const url = new URL(c.req.url);
70	  url.pathname = "/";
71	  return setupSub.fetch(new Request(url.toString(), c.req.raw));
72	});
73	
74	// ---------------------------------------------------------------------------
75	// R2-native upload endpoints (registered before the /api/* catch-all)
76	// ---------------------------------------------------------------------------
77	
78	registerUploadHandlers(app);
79	
80	// ---------------------------------------------------------------------------
81	// CF-native implementations of routes that use raw Express handlers or depend
82	// on runtime registries not present in CF Workers (adapters, plugins, access)
83	// ---------------------------------------------------------------------------
84	
85	registerCfExtraRoutes(app);
86	
87	// ---------------------------------------------------------------------------
88	// Main API catch-all
89	//
90	// Manual routing: iterate compiled route definitions, match method + path,
91	// and invoke the transport-agnostic Handler. Using a single wildcard route
92	// avoids blowing Hono's internal route trie limit (229+ routes).
93	// ---------------------------------------------------------------------------
94	
95	app.all("/api/*", async (c) => {
96	  const { compiled, db, storage } = buildRequestResources(c.env);
97	
98	  // Normalize trailing slash so /api/companies/ matches /api/companies routes.
99	  const rawPathname = new URL(c.req.url).pathname;
100	  const pathname = rawPathname.length > 1 ? rawPathname.replace(/\/$/, "") : rawPathname;
101	  const method = c.req.method.toUpperCase();
102	
103	  for (const { route, re, paramNames } of compiled) {
104	    if (route.method !== method) continue;
105	    const match = re.exec(pathname);
106	    if (!match) continue;
107	
108	    const params: Record<string, string> = {};
109	    for (let i = 0; i < paramNames.length; i++) {
110	      params[paramNames[i]!] = match[i + 1]!;
111	    }
112	
113	    const actor = await resolveActorFromRequest(c.req.raw, db, {
114	      deploymentMode: resolveDeploymentMode(c.env),
115	    });
116	
117	    const ctx: import("../../../../server/src/http/types.js").RequestCtx = {
118	      method: c.req.method,
119	      url: new URL(c.req.url),
120	      headers: new Headers(c.req.raw.headers),
121	      json<T>(): Promise<T> { return c.req.json<T>(); },
122	      text(): Promise<string> { return c.req.text(); },
123	      param(name: string): string | undefined { return params[name]; },
124	      query(name: string): string | undefined { return c.req.query(name); },
125	      actor,
126	      db,
127	      storage,
128	    };
129	
130	    try {
131	      return await route.handler(ctx);
132	    } catch (err) {
133	      if (err instanceof HttpError) {
134	        return Response.json(
135	          { error: err.message, ...(err.details !== undefined ? { details: err.details } : {}) },
136	          { status: err.status },
137	        );
138	      }
139	      console.error(
140	        `[CF Worker] Unhandled error in ${route.method} ${route.path}: ${
141	          err instanceof Error ? (err.stack ?? err.message) : String(err)
142	        }`,
143	      );
144	      return Response.json({ error: "Internal Server Error" }, { status: 500 });
145	    }
146	  }
147	
148	  return c.json(
149	    { error: "This API route is not available in the Cloudflare Workers deployment.", code: "NOT_IMPLEMENTED" },
150	    501,
151	  );
152	});
153	
154	// ---------------------------------------------------------------------------
155	// SPA fallback — delegates to the ASSETS binding (Workers Static Assets).
156	// CF serves the matching file from ui/dist, or index.html for unknown paths
157	// (not_found_handling = "single-page-application" in wrangler.toml).
158	// ---------------------------------------------------------------------------
159	
160	app.all("*", (c) => c.env.ASSETS.fetch(c.req.raw));
161	

